#!/usr/bin/env bash
set -euo pipefail
ROOT_DIR=$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")/.." && pwd)
: "${REDEVEN_VITEST_BROWSER_PORT:?Select an isolated task-owned browser port}"
cd "$ROOT_DIR"
node scripts/check_unified_settings.mjs
cd internal/envapp/ui_src
npx vitest run --environment=node --maxWorkers=2 src/ui/EnvAppThemePicker.test.tsx src/ui/pages/settings/unifiedSettingsContract.test.ts src/ui/pages/settings/SettingsPrimitives.test.tsx src/ui/pages/settings/SettingsSelect.test.tsx src/ui/pages/settings/settingsStructure.test.ts src/ui/pages/settings/TerminalSettingsPanel.test.tsx src/ui/services/terminalSettingsTargets.test.tsx src/ui/pages/settings/ContainerSettingsPanel.test.tsx src/ui/services/containerResourcesApi.test.ts src/ui/pages/settings/ApplicationPictureSettings.test.tsx src/ui/pages/settings/DesktopAuthorizationSettings.test.tsx src/ui/pages/settings/ConversationDefaultsSettings.test.tsx src/ui/pages/settings/DisplayPreferencesSettings.test.tsx src/ui/services/computerViewerPreferences.test.ts src/ui/services/workbenchLocalPreferences.test.ts src/ui/services/hostApplicationSettingsTarget.test.ts src/ui/services/hostApplicationPicture.test.ts src/ui/plugins/PluginSettingsPanel.test.tsx src/ui/plugins/pluginSettingsTarget.test.ts src/ui/pages/settings/FlowerSettingsPanel.test.tsx src/ui/pages/EnvSettingsPage.test.tsx src/ui/pages/EnvPortForwardsPage.test.tsx src/ui/pages/EnvHostApplicationsPage.test.tsx src/ui/EnvAppShell.localAccess.e2e.test.tsx src/ui/MobileShellTools.test.tsx src/ui/plugins/PluginCenterView.test.tsx src/ui/i18n/i18n.test.ts
npm run test:browser -- src/ui/pages/settings/EnvSettingsAllCategories.browser.test.tsx src/ui/pages/settings/ContainerSettingsPanel.browser.test.tsx src/ui/plugins/PluginSettingsPanel.browser.test.tsx src/ui/pages/RuntimeSettingsDesign.browser.test.tsx src/ui/FlowerComputerDialog.browser.test.tsx src/ui/pages/HostAccess.browser.test.tsx src/ui/FlowerSurface.computerStage.browser.test.tsx src/ui/pages/settings/EnvSettingsDialog.browser.test.tsx src/ui/pages/settings/UnifiedSettings.browser.test.tsx src/ui/pages/ManagedServiceSettingsDesign.browser.test.tsx src/ui/pages/settings/CodeRuntimeSettingsCard.browser.test.tsx src/ui/FlowerComputerConnections.browser.test.tsx src/ui/flower/FlowerExtensions.browser.test.tsx src/ui/widgets/TerminalSettingsDialog.browser.test.tsx src/ui/widgets/TerminalHistorySettings.browser.test.tsx src/ui/plugins/PluginConnectionsDialog.browser.test.tsx src/ui/plugins/PluginAuthorAccess.browser.test.tsx
cd "$ROOT_DIR/desktop"
npx vitest run --maxWorkers=2 src/main/runtimeSettingsTarget.test.ts src/main/hostApplicationWindow.test.ts src/main/mainRouting.test.ts src/welcome/environmentSettingsSession.test.ts src/welcome/App.test.tsx ../internal/flower_ui/src/browserInstallationController.test.ts
npx vitest run --config vitest.client.config.mts --maxWorkers=2 src/welcome/DesktopSettingsDialog.client.test.tsx src/welcome/EnvironmentSettingsEntry.client.test.tsx src/welcome/flower/localEnvironmentFlowerSurfaceAdapter.client.test.tsx src/welcome/DesktopThemePicker.client.test.tsx
